#ifndef SWGXR_FACTORIES_H
#define SWGXR_FACTORIES_H
#include "SwgxrHarvesters.h"
#include "server/zone/objects/installation/factory/FactoryObject.h"
#include "server/zone/objects/manufactureschematic/ManufactureSchematic.h"
#include "server/zone/objects/draftschematic/DraftSchematic.h"
#include "templates/installation/FactoryObjectTemplate.h"

// Native schematics, hoppers and factory tasks remain the sole production authority.
// Redeeding transfers the original deed synchronously but queues world deletion.
class SwgxrFactories {
 using Json=JSONSerializationType;
 static std::string id(SceneObject* o){return o?std::to_string(o->getObjectID()):"0";}
 static std::string text(const String& s){return s.toCharArray();}
 static ManufactureSchematic* installed(FactoryObject* f){return f->getContainerObjectsSize()>0?dynamic_cast<ManufactureSchematic*>(f->getContainerObject(0).get()):nullptr;}
 static bool compatible(FactoryObject* f,ManufactureSchematic* s){auto t=dynamic_cast<FactoryObjectTemplate*>(f->getObjectTemplate());if(!t || !s || !s->getDraftSchematic() || !s->getPrototype() || s->getManufactureLimit()<=0)return false;auto tabs=t->getCraftingTabsSupported();for(int i=0;i<tabs.size();++i)if(tabs.get(i)==s->getDraftSchematic()->getToolTab())return true;return false;}
 static Json blueprint(ManufactureSchematic* s){if(!s)return Json::object();return {{"id",id(s)},{"name",text(s->getDisplayedName())},{"template",text(s->getObjectTemplate()->getFullTemplateString())},{"category","data"},{"type","manufacturing_blueprint"},{"deletable",false},{"manufacture_limit",s->getManufactureLimit()},{"description","Source manufacturing blueprint. Drag into a compatible factory."}};}
 static Json item(SceneObject* o,CreatureObject* c){auto row=SwgxrInventory::describe(o,c);row["name"]=text(o->getDisplayedName());return row;}
 static Json contents(SceneObject* hopper,CreatureObject* c){Json rows=Json::array();if(hopper)for(int i=0;i<hopper->getContainerObjectsSize();++i)rows.push_back(item(hopper->getContainerObject(i),c));return rows;}
 // Mirrors native collectMatchesInInputHopper: exact spawn; component CRC and serial.
 static bool matches(BlueprintEntry* e,TangibleObject* o){if(!o)return false;if(o->isResourceContainer())return e->getKey()==static_cast<ResourceContainer*>(o)->getSpawnName();auto p=o->isFactoryCrate()?static_cast<FactoryCrate*>(o)->getPrototype().get():o;return p && e->getKey()==String::valueOf(p->getServerObjectCRC()) && (!e->needsIdentical() || e->getSerial()==p->getSerialNumber());}
 static void refresh(FactoryObject* f){auto s=installed(f);auto hopper=f->getSlottedObject("ingredient_hopper");if(!s || !hopper)return;for(int i=0;i<s->getBlueprintSize();++i){auto e=s->getBlueprintEntry(i);e->setHopper(hopper);e->clearMatches();for(int j=0;j<hopper->getContainerObjectsSize();++j){auto o=dynamic_cast<TangibleObject*>(hopper->getContainerObject(j).get());if(matches(e,o))e->addMatch(o);}}}
 static void transfer(CreatureObject* c,SceneObject* o,SceneObject* destination){auto cmd=c->getZoneServer()->getObjectController()->getQueueCommand("transferitemmisc");auto args=id(destination)+" -1 0 0 0";if(!cmd || cmd->doQueueCommand(c,o->getObjectID(),UnicodeString(String(args.c_str())))!=QueueCommand::SUCCESS || o->getParentID()!=destination->getObjectID())throw std::runtime_error("Native factory transfer rejected: permissions, range or capacity");o->updateToDatabaseAllObjects(false);}
public:
 static bool supports(SceneObject* o){return o && o->isFactory();}
 static bool deed(SceneObject* o){auto d=dynamic_cast<StructureDeed*>(o);return d && text(d->getGeneratedObjectTemplate()).find("object/installation/manufacture/")==0;}
 static void deeds(CreatureObject* c,SceneObject* parent,Json& out,int depth=0){if(!parent || depth>8)return;for(int i=0;i<parent->getContainerObjectsSize() && out.size()<128;++i){auto o=parent->getContainerObject(i);if(deed(o))out.push_back(SwgxrInventory::describe(o,c));if(o->getContainerVolumeLimit()>0 && !o->isFactoryCrate())deeds(c,o,out,depth+1);}}
 static Json blueprints(CreatureObject* c){Json rows=Json::array();auto pad=c->getSlottedObject("datapad");if(pad)for(int i=0;i<pad->getContainerObjectsSize() && rows.size()<256;++i){auto s=dynamic_cast<ManufactureSchematic*>(pad->getContainerObject(i).get());if(s && s->getPrototype() && s->getManufactureLimit()>0)rows.push_back(blueprint(s));}return rows;}
 static Json view(CreatureObject* c,FactoryObject* f){auto input=f->getSlottedObject("ingredient_hopper"),output=f->getSlottedObject("output_hopper");auto s=installed(f);Json out={{"id",id(f)},{"active",f->isActive()},{"blueprint",blueprint(s)},{"blueprints",blueprints(c)},{"requirements",Json::array()},{"input",contents(input,c)},{"output",contents(output,c)},{"input_capacity",input?input->getContainerVolumeLimit():0},{"output_capacity",output?output->getContainerVolumeLimit():0},{"power",f->getSurplusPower()},{"power_rate",f->getBasePowerRate()},{"maintenance",f->getSurplusMaintenance()},{"maintenance_rate",f->getMaintenanceRate()},{"cash",c->getCashCredits()},{"owner",f->isOwnerOf(c)},{"redeed_cost",f->getRedeedCost()},{"redeedable",f->isRedeedable()}};if(s)for(int i=0;i<s->getBlueprintSize();++i){auto e=s->getBlueprintEntry(i);out["requirements"].push_back({{"name",text(e->getDisplayedName())},{"type",text(e->getType())},{"key",text(e->getKey())},{"serial",text(e->getSerial())},{"identical",e->needsIdentical()},{"quantity",e->getQuantity()}});}return out;}
 static Json execute(CreatureObject* c,const Json& r){
  auto f=c->getZoneServer()->getObject(std::stoull(r.at("structure_id").get<std::string>())).castTo<FactoryObject*>();if(!f || f->getZone()!=c->getZone() || c->getParentID()!=0 || !c->isInRange(f,16))throw std::runtime_error("Factory out of reach");Locker lock(f,c);if(f->getDeedObjectID()==0)throw std::runtime_error("Factory recovery already pending");if(!f->isOnAdminList(c))throw std::runtime_error("Factory administrator permission required");auto action=r.at("action").get<std::string>();Json result=Json::object();auto input=f->getSlottedObject("ingredient_hopper"),output=f->getSlottedObject("output_hopper");if(!input || !output)throw std::runtime_error("Native factory hoppers unavailable");
  if(action=="house_factory_blueprint"){
   auto s=c->getZoneServer()->getObject(std::stoull(r.at("item_id").get<std::string>())).castTo<ManufactureSchematic*>();auto pad=c->getSlottedObject("datapad");if(f->isActive() || installed(f) || !s || !pad || s->getParentID()!=pad->getObjectID() || !compatible(f,s))throw std::runtime_error("Stop factory and insert an owned compatible manufacturing blueprint into its empty slot");Locker schematicLock(s,c);f->handleInsertFactorySchem(c,s);if(s->getParentID()!=f->getObjectID())throw std::runtime_error("Native blueprint insertion rejected");s->updateToDatabaseAllObjects(false);refresh(f);
  }else if(action=="house_factory_remove_blueprint"){
   if(f->isActive() || !installed(f))throw std::runtime_error("Stop factory before removing its blueprint");ManagedReference<ManufactureSchematic*> s=installed(f);if(!f->handleRemoveFactorySchem(c))throw std::runtime_error("Native blueprint removal rejected: datapad capacity");s->updateToDatabaseAllObjects(false);
  }else if(action=="house_factory_input" || action=="house_factory_withdraw" || action=="house_factory_collect"){
   auto o=c->getZoneServer()->getObject(std::stoull(r.at("item_id").get<std::string>()));if(!o)throw std::runtime_error("Factory item unavailable");Locker itemLock(o,c);
   if(action=="house_factory_input"){auto s=installed(f);if(!s || !SwgxrEquipment::inInventory(o,c))throw std::runtime_error("Installed blueprint and owned ingredient required");bool accepts=false;for(int i=0;i<s->getBlueprintSize();++i)if(matches(s->getBlueprintEntry(i),dynamic_cast<TangibleObject*>(o.get())))accepts=true;if(!accepts)throw std::runtime_error("Ingredient does not match source blueprint resource or component serial");transfer(c,o,input);}
   else {auto source=action=="house_factory_withdraw"?input:output;if(o->getParentID()!=source->getObjectID())throw std::runtime_error("Item does not belong to this factory hopper");transfer(c,o,c->getInventory());}refresh(f);
  }else if(action=="house_factory_active"){
   bool desired=r.at("active").get<bool>();if(desired && (!installed(f) || f->getSurplusPower()<=0 || f->getSurplusMaintenance()<=0))throw std::runtime_error("Blueprint, upkeep and energy required");if(f->isActive()!=desired)f->handleOperateToggle(c);if(f->isActive()!=desired)throw std::runtime_error("Native factory operation rejected");
  }else if(action=="house_factory_power"){
   auto container=c->getZoneServer()->getObject(std::stoull(r.at("item_id").get<std::string>())).castTo<ResourceContainer*>();if(!container || !SwgxrEquipment::inInventory(container,c))throw std::runtime_error("Owned energy resource required");Locker resourceLock(container,c);auto spawn=container->getSpawnObject();if(!spawn || !spawn->isEnergy() || container->getQuantity()<=0 || f->getBasePowerRate()==0)throw std::runtime_error("This resource or factory cannot accept power");int64 energy=int64(std::max(1.0f,spawn->getValueOf(CraftingManager::PE)/500.0f)*container->getQuantity());if(energy<=0 || energy>INT_MAX-f->getSurplusPower())throw std::runtime_error("Power reserve limit");f->addPower(energy);container->destroyObjectFromWorld(true);container->destroyObjectFromDatabase(true);result["power_deposited"]=energy;
  }else if(action=="house_factory_deposit"){
   int amount=r.at("amount").get<int>();if(amount<=0 || amount>c->getCashCredits() || amount>100000000-f->getSurplusMaintenance())throw std::runtime_error("Invalid maintenance deposit");auto before=c->getCashCredits();StructureManager::instance()->payMaintenance(f,c,amount);if(before-c->getCashCredits()!=amount)throw std::runtime_error("Maintenance deposit rejected");
  }else if(action=="house_factory_recover"){
   if(!f->isOwnerOf(c) || f->isActive() || installed(f) || input->getContainerObjectsSize()>0 || output->getContainerObjectsSize()>0 || !f->isRedeedable() || f->getDeedObjectID()==0 || c->containsActiveSession(SessionFacadeType::DESTROYSTRUCTURE))throw std::runtime_error("Owner, stopped empty factory and native redeeding requirements required");auto original=c->getZoneServer()->getObject(f->getDeedObjectID()).castTo<StructureDeed*>();if(!original)throw std::runtime_error("Original factory deed unavailable");for(auto field:{"left_hand","right_hand"}){auto p=r.at(field);Vector3 hand(p[0].get<float>(),p[2].get<float>(),p[1].get<float>());if(hand.distanceTo(c->getWorldPosition())>3.5 || hand.distanceTo(f->getWorldPosition())>std::max(2.f,f->getTemplateRadius()+.25f))throw std::runtime_error("Both hands must touch the factory");}if(c->getInventory()->isContainerFullRecursive())throw std::runtime_error("Inventory space required for original deed");Reference<DestroyStructureSession*> session=new DestroyStructureSession(c,f);c->addActiveSession(SessionFacadeType::DESTROYSTRUCTURE,session);StructureManager::instance()->redeedStructure(c);if(f->getDeedObjectID()!=0 || !SwgxrEquipment::inInventory(original,c))throw std::runtime_error("Native factory recovery rejected");original->updateToDatabaseAllObjects(false);result["recovered_deed_id"]=id(original);return result;
  }else if(action!="house_factory_status")throw std::runtime_error("Unknown factory action");
  if(action!="house_factory_status")f->updateToDatabaseAllObjects(false);result["factory"]=view(c,f);return result;
 }
};
#endif
